/**
 * Build-time integrity check — runs on import, throws loudly on failure.
 * Every era must have exactly 72 investments (36 Good / 36 Bad), and every
 * `percentage` must be a finite number.
 */
(function assertEras(eras) {
  for (const era of eras) {
    if (era.investments.length !== 72) {
      throw new Error(`[eras.js] era "${era.id}": expected 72 investments, got ${era.investments.length}`);
    }
    const goodCount = era.investments.filter((inv) => inv.type === 'Good').length;
    const badCount = era.investments.filter((inv) => inv.type === 'Bad').length;
    if (goodCount !== 36 || badCount !== 36) {
      throw new Error(`[eras.js] era "${era.id}": expected 36 Good / 36 Bad, got ${goodCount} Good / ${badCount} Bad`);
    }
    for (const inv of era.investments) {
      if (typeof inv.percentage !== 'number' || !Number.isFinite(inv.percentage)) {
        throw new Error(`[eras.js] era "${era.id}", investment "${inv.id}": percentage is not a finite number (${inv.percentage})`);
      }
    }
  }
})(ERAS);
